<?php require 'config/config.php';auth();$s=db()->prepare("SELECT b.*,r.room_number,r.rent,p.title,p.city,a.id agreement_id,a.agreement_no FROM bookings b JOIN rooms r ON r.id=b.room_id JOIN properties p ON p.id=r.property_id LEFT JOIN rental_agreements a ON a.booking_id=b.id WHERE b.user_id=? ORDER BY b.created_at DESC");$s->execute([user()['id']]);$bs=$s->fetchAll();$title='Dashboard';require 'config/header.php';?><div class="head"><small>MY SPACE</small><h1>Hello, <?=e(user()['name'])?> 👋</h1></div><div class="stats"><div><b><?=count($bs)?></b><span>Bookings</span></div><div><b><?=count(array_filter($bs,fn($x)=>$x['agreement_id']))?></b><span>Agreements</span></div><div><b><?=money(array_sum(array_column($bs,'advance_amount')))?></b><span>Booked advance</span></div></div><div class="panel"><h2>My bookings</h2><?php foreach($bs as $b):?><div class="row"><div><b><?=e($b['title'])?></b><p><?=e($b['city'])?> · Room <?=e($b['room_number'])?></p></div><div><?php if($b['status']==='pending_payment'):?><a href="<?=BASE_URL?>/pay.php?booking_id=<?=$b['id']?>">Pay advance</a><?php elseif($b['agreement_id']):?><a href="<?=BASE_URL?>/agreement.php?id=<?=$b['agreement_id']?>">View agreement</a> · <a href="<?=BASE_URL?>/agreement_pdf.php?id=<?=$b['agreement_id']?>">PDF</a><?php else:?>Confirmed<?php endif;?></div></div><?php endforeach;?><?php if(!$bs):?><p>No bookings yet.</p><?php endif;?></div><?php require 'config/footer.php';?>
